on conflict (id) do update set
  name=excluded.name, brand=excluded.brand, model=excluded.model, year=excluded.year,
  mileage=excluded.mileage, transmission=excluded.transmission, fuel=excluded.fuel,
  body=excluded.body, engine=excluded.engine, power=excluded.power, price=excluded.price,
  installment=excluded.installment, description=excluded.description,
  images=excluded.images, stock=excluded.stock, sort_order=excluded.sort_order,
  updated_at=now();

alter table public.testimonials add column if not exists source text not null default 'Direct';

on conflict (id) do update set
  name=excluded.name, rating=excluded.rating, review=excluded.review,
  source=excluded.source, updated_at=now();

on conflict (key) do update set value=excluded.value, updated_at=now();
